## 1. Make the DeepL calls asynchronous and reuse connections

Here’s an illustrative implementation using your existing Axios/ioredis approach. It standardizes the payload as `{ text, target_lang, source_lang? }`.

```javascript
const axios = require("axios");
const https = require("node:https");
const { createHash } = require("node:crypto");

// Reuse one client across requests, rather than creating it in the route.
const deepl = axios.create({
  baseURL: "https://api.deepl.com/v2",
  headers: {
    Authorization: `DeepL-Auth-Key ${process.env.DEEPL_API_KEY}`
  },
  httpsAgent: new https.Agent({
    keepAlive: true,
    maxSockets: 20 // Illustrative; tune with load tests.
  }),
  timeout: 1000 // Safety timeout, not a promise of sub-200 ms latency.
});

const inFlight = new Map();

function cacheKey(text, targetLang, sourceLang) {
  const hash = createHash("sha256")
    .update(JSON.stringify([text, sourceLang || "auto", targetLang]))
    .digest("hex");

  return `translation:v1:${hash}`;
}

// Pass in your existing, shared ioredis client.
async function translateText(redis, text, targetLang, sourceLang) {
  const key = cacheKey(text, targetLang, sourceLang);

  // Redis failure should not prevent translation.
  try {
    if (redis.status === "ready") {
      const cached = await redis.get(key);
      if (cached !== null) {
        return { translated_text: cached, cached: true, fallback: false };
      }
    }
  } catch (error) {
    console.warn("Translation cache read failed:", error.message);
  }

  // Collapse simultaneous identical requests into one upstream call.
  if (inFlight.has(key)) return inFlight.get(key);

  const pending = (async () => {
    const body = new URLSearchParams({
      text,
      target_lang: targetLang
    });

    if (sourceLang) body.set("source_lang", sourceLang);

    const response = await deepl.post("/translate", body);
    const translated = response.data.translations[0].text;

    // Do not delay the response while waiting for a cache write.
    if (redis.status === "ready") {
      void redis.set(key, translated, "EX", 900).catch(error => {
        console.warn("Translation cache write failed:", error.message);
      });
    }

    return {
      translated_text: translated,
      cached: false,
      fallback: false
    };
  })();

  inFlight.set(key, pending);

  try {
    return await pending;
  } finally {
    inFlight.delete(key);
  }
}
```

The **900-second TTL** is an illustrative starting point matching your earlier 15-minute cache. Configure Redis with short command timeouts and avoid queuing commands indefinitely during outages.

The `inFlight` map prevents duplicate work **within one service instance**; it does not deduplicate across multiple containers.

